pub const INPUT_LIMIT: i32 = 100;

pub fn adjust(value: i32) -> i32 {
    value + 1
}

pub fn normalize(value: i32) -> i32 {
    let adjusted = adjust(value.saturating_sub(1));
    adjusted * 2
}

pub fn consume(value: i32) -> i32 {
    normalize(value)
}
